const LEVEL_COLORS = ['var(--lvl-elementary)','var(--lvl-preint)','var(--lvl-intermediate)','var(--lvl-intplus)','var(--lvl-upperint)'];

function buildRays(container) {
  const RAY_COUNT = 10;
  for (let i = 0; i < RAY_COUNT; i++) {
    const ray = document.createElement('div');
    ray.className = 'ray';
    const angle = (360 / RAY_COUNT) * i;
    ray.style.setProperty('--ang', angle + 'deg');
    ray.style.setProperty('--ray-color', LEVEL_COLORS[i % LEVEL_COLORS.length]);
    container.appendChild(ray);
  }
}
['raysMenu','raysLevel','raysSettings','raysTeams','raysEnd'].forEach(id => buildRays(document.getElementById(id)));

function burst(el) { el.classList.remove('burst'); void el.offsetWidth; el.classList.add('burst'); }

// generic "тык" burst for any button — builds a one-off rays wrapper
// positioned right over whatever was clicked, so every button gets the
// same tactile feedback without needing a hand-placed <div class="rays">
function burstAt(el) {
  if (!el) return;
  const rect = el.getBoundingClientRect();
  const wrap = document.createElement('div');
  wrap.className = 'rays';
  wrap.style.position = 'fixed';
  wrap.style.left = (rect.left + rect.width / 2) + 'px';
  wrap.style.top = (rect.top + rect.height / 2) + 'px';
  wrap.style.right = 'auto';
  wrap.style.bottom = 'auto';
  wrap.style.width = '0px';
  wrap.style.height = '0px';
  wrap.style.zIndex = '2000';
  buildRays(wrap);
  document.body.appendChild(wrap);
  wrap.classList.add('burst');
  setTimeout(() => wrap.remove(), 650);
}

// ═══ retro sound (Web Audio, no files) ═══
let audioCtx = null;
let soundOn = true;
function ensureAudio() {
  if (!audioCtx) { try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { audioCtx = null; } }
  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
}
function tone(freq, start, dur, type, gainVal) {
  if (!audioCtx) return;
  const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain();
  osc.type = type || 'square';
  osc.frequency.setValueAtTime(freq, audioCtx.currentTime + start);
  gain.gain.setValueAtTime(0, audioCtx.currentTime + start);
  gain.gain.linearRampToValueAtTime(gainVal || 0.22, audioCtx.currentTime + start + 0.01);
  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + start + dur);
  osc.connect(gain).connect(audioCtx.destination);
  osc.start(audioCtx.currentTime + start); osc.stop(audioCtx.currentTime + start + dur + 0.02);
}
function playStartJingle() {
  if (!soundOn) return;
  ensureAudio();
  const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain();
  osc.type = 'square';
  const t0 = audioCtx.currentTime;
  osc.frequency.setValueAtTime(220, t0);
  osc.frequency.exponentialRampToValueAtTime(660, t0 + 0.12);
  gain.gain.setValueAtTime(0.001, t0);
  gain.gain.linearRampToValueAtTime(0.19, t0 + 0.02);
  gain.gain.exponentialRampToValueAtTime(0.001, t0 + 0.13);
  osc.connect(gain).connect(audioCtx.destination);
  osc.start(t0); osc.stop(t0 + 0.14);
  tone(523, 0.14, 0.09, 'square', 0.20);
  tone(659, 0.22, 0.09, 'square', 0.20);
  tone(784, 0.30, 0.09, 'square', 0.21);
  tone(1046, 0.38, 0.30, 'square', 0.23);
}
function playConfirmBlip() {
  if (!soundOn) return;
  ensureAudio();
  tone(660, 0,    0.08, 'sine', 0.17);
  tone(880, 0.05, 0.16, 'triangle', 0.16);
}

// ═══ screen nav ═══
// Every transition waits for the burst animation (≈550ms) to fully play
// before the screen changes, so the "тык" effect is never cut off or
// covered by the button/next screen.
function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
  document.body.classList.toggle('in-game', id === 'screenGame');
  window.scrollTo(0, 0);
}

function handleStart() {
  ensureAudio();
  playStartJingle();
  const btn = document.getElementById('ctaBtn');
  btn.classList.remove('press'); void btn.offsetWidth; btn.classList.add('press');
  setTimeout(() => btn.classList.remove('press'), 400);
  burst(document.getElementById('raysMenu'));
  setTimeout(() => showScreen('screenLevel'), 560);
}

function handleNext(targetId, btnEl, raysId) {
  ensureAudio();
  playConfirmBlip();
  btnEl.classList.remove('press'); void btnEl.offsetWidth; btnEl.classList.add('press');
  setTimeout(() => btnEl.classList.remove('press'), 150);
  setTimeout(() => showScreen(targetId), 560);
}

function handlePlay() {
  ensureAudio();
  playConfirmBlip();
  const btn = document.getElementById('btnPlay');
  btn.classList.remove('press'); void btn.offsetWidth; btn.classList.add('press');
  setTimeout(() => btn.classList.remove('press'), 150);
  setTimeout(startGame, 560);
}

// ═══ LEVELS ═══
// Each level's word list lives in its own .txt file under dictionaries/ —
// see README.md for the file format. Add a new level by adding a row here
// and dropping a matching .txt file next to this page.
const LEVELS = [
  { id: 'elementary',        label: 'Elementary',         color: 'var(--lvl-elementary)',  file: 'dictionaries/elementary.txt' },
  { id: 'preint',            label: 'Pre-Intermediate',   color: 'var(--lvl-preint)',       file: 'dictionaries/pre-intermediate.txt' },
  { id: 'intermediate',      label: 'Intermediate',       color: 'var(--lvl-intermediate)', file: 'dictionaries/intermediate.txt' },
  { id: 'intplus',           label: 'Intermediate Plus',  color: 'var(--lvl-intplus)',      file: 'dictionaries/intermediate-plus.txt' },
  { id: 'upperint',          label: 'Upper-Intermediate', color: 'var(--lvl-upperint)',     file: 'dictionaries/upper-intermediate.txt' },
];
let selectedLevel = 'preint';

// filled in once the selected level's dictionary has loaded
let CATEGORIES = [];               // [{ id, label }]
let WORDS = {};                     // { [catId]: [{ word, hint? }] }
let dictionariesLoaded = {};        // cache: levelId -> { categories, words }
let levelLoadError = null;

function buildLevelList() {
  const wrap = document.getElementById('levelList');
  wrap.innerHTML = '';
  LEVELS.forEach(lvl => {
    const row = document.createElement('div');
    row.className = 'level-row' + (lvl.id === selectedLevel ? ' active' : '');
    row.style.setProperty('--lvl-color', lvl.color);
    row.innerHTML = `<div class="dot"></div><div class="name">${lvl.label}</div>`;
    row.onclick = () => { burstAt(row); selectedLevel = lvl.id; buildLevelList(); syncLevelColor(); };
    wrap.appendChild(row);
  });
}

// the chosen level's color becomes the wizard's accent for every
// remaining screen — title, toggles, progress dots, Next/Play buttons
function syncLevelColor() {
  const lvl = LEVELS.find(l => l.id === selectedLevel);
  document.documentElement.style.setProperty('--wiz-color', lvl.color);
  document.querySelectorAll('.screen').forEach(s => { if (s.id !== 'screenMenu') s.style.setProperty('--wiz-color', lvl.color); });
}
buildLevelList();
syncLevelColor();

// ═══ dictionary loading & parsing ═══
// Format: "## Category name" starts a category, plain lines are words,
// "word | hint" attaches an optional hint, "//" lines are comments.
function slugifyCat(label, i) {
  const base = label.toLowerCase().replace(/[^a-z0-9а-яё]+/gi, '-').replace(/^-+|-+$/g, '');
  return (base || 'cat') + '-' + i;
}
function parseDictionary(text) {
  const lines = text.split(/\r?\n/);
  const categories = []; const words = {};
  let currentId = null;
  lines.forEach(raw => {
    const line = raw.trim();
    if (!line || line.startsWith('//')) return;
    if (line.startsWith('## ')) {
      const label = line.slice(3).trim();
      const id = slugifyCat(label, categories.length);
      categories.push({ id, label }); words[id] = []; currentId = id;
      return;
    }
    if (!currentId) return;
    const parts = line.split('|');
    const word = parts[0].trim();
    if (!word) return;
    const hint = parts[1] ? parts[1].trim() : undefined;
    words[currentId].push(hint ? { word, hint } : { word });
  });
  return { categories, words };
}

// called when the person taps "Next" on the level screen — fetches (or
// reuses a cached copy of) the selected level's dictionary before moving on
function handleLevelNext() {
  const btn = document.getElementById('btnLevelNext');
  const loadingRow = document.getElementById('levelLoadingRow');
  const errorNote = document.getElementById('levelErrorNote');
  errorNote.style.display = 'none';

  if (dictionariesLoaded[selectedLevel]) {
    applyLoadedDictionary(dictionariesLoaded[selectedLevel]);
    handleNext('screenTopics', btn, 'raysLevel');
    return;
  }

  loadingRow.style.display = 'flex';
  btn.disabled = true;
  const lvl = LEVELS.find(l => l.id === selectedLevel);
  fetch(lvl.file, { cache: 'no-store' })
    .then(res => { if (!res.ok) throw new Error('HTTP ' + res.status); return res.text(); })
    .then(text => {
      const parsed = parseDictionary(text);
      dictionariesLoaded[selectedLevel] = parsed;
      loadingRow.style.display = 'none';
      btn.disabled = false;
      applyLoadedDictionary(parsed);
      handleNext('screenTopics', btn, 'raysLevel');
    })
    .catch(err => {
      loadingRow.style.display = 'none';
      btn.disabled = false;
      errorNote.style.display = 'block';
      errorNote.textContent = `Couldn't load the dictionary (${lvl.file}): ${err.message}. If you opened this file directly from disk, try a local server or GitHub Pages instead.`;
    });
}

function handleTopicsNext(btn) {
  if (selectedTopics.length === 0) return;
  handleNext('screenSettings', btn, 'raysTopics');
}

function applyLoadedDictionary(parsed) {
  CATEGORIES = parsed.categories;
  WORDS = parsed.words;
  selectedTopics = CATEGORIES.map(c => c.id);
  buildTopicPills();
  const hint = document.getElementById('topicsHint');
  hint.textContent = CATEGORIES.length === 0
    ? 'This dictionary is currently empty — add categories and words to its .txt file to play this level.'
    : '';
}

// ═══ TOPICS (Vocabulary Bank) — built from the loaded dictionary ═══
let selectedTopics = []; // filled once a level's dictionary loads

function buildTopicPills() {
  const wrap = document.getElementById('topicPills');
  wrap.innerHTML = '';
  CATEGORIES.forEach(topic => {
    const btn = document.createElement('button');
    btn.className = 'pill' + (selectedTopics.includes(topic.id) ? ' active' : '');
    btn.textContent = formatTopicLabel(topic.label);
    btn.onclick = () => {
      burstAt(btn);
      if (selectedTopics.includes(topic.id)) {
        if (selectedTopics.length > 1) selectedTopics = selectedTopics.filter(id => id !== topic.id);
      } else {
        selectedTopics.push(topic.id);
      }
      buildTopicPills();
    };
    wrap.appendChild(btn);
  });
}
function selectAllTopics() {
  if (CATEGORIES.length === 0) return;
  selectedTopics = CATEGORIES.map(t => t.id);
  buildTopicPills();
}
function clearAllTopics() {
  selectedTopics = [];
  buildTopicPills();
}

// "Words From Other Languages — File 6B"  ->  "6B | Words From Other Languages"
// (categories without a "File X" suffix are shown unchanged)
function formatTopicLabel(label) {
  const m = label.match(/^(.*?)\s*—\s*File\s+(\d+[A-Za-z]?)\s*$/i);
  return m ? `${m[2]} | ${m[1].trim()}` : label;
}
buildTopicPills();

// ═══ steppers ═══
let timerVal = 60, roundsVal = 3;
function adjTimer(d) { timerVal = Math.min(180, Math.max(20, timerVal + d)); document.getElementById('timerVal').textContent = timerVal; }
function adjRounds(d) { roundsVal = Math.min(10, Math.max(1, roundsVal + d)); document.getElementById('roundsVal').textContent = roundsVal; }

// ═══ TEAMS ═══
let teams = [{ name: 'Team A' }, { name: 'Team B' }];
function buildTeamsList() {
  const list = document.getElementById('teamsList');
  list.innerHTML = '';
  teams.forEach((t, i) => {
    const row = document.createElement('div');
    row.className = 'team-row';
    row.innerHTML = `<div class="team-dot"></div>`;
    row.querySelector('.team-dot').style.background = LEVEL_COLORS[i % LEVEL_COLORS.length];
    const input = document.createElement('input');
    input.className = 'team-input';
    input.value = t.name;
    input.oninput = () => { teams[i].name = input.value; };
    row.appendChild(input);
    const removeBtn = document.createElement('button');
    removeBtn.className = 'team-remove-btn';
    removeBtn.type = 'button';
    removeBtn.textContent = '✕';
    removeBtn.disabled = teams.length <= 2;
    removeBtn.onclick = () => { burstAt(removeBtn); removeTeamAt(i); };
    row.appendChild(removeBtn);
    list.appendChild(row);
  });
  document.getElementById('btnAddTeam').disabled = teams.length >= 6;
}
function nextTeamLetter() {
  const used = new Set(
    teams.map(t => (t.name.match(/^Team ([A-Z])$/) || [])[1]).filter(Boolean)
  );
  for (let i = 0; i < 26; i++) {
    const letter = String.fromCharCode(65 + i);
    if (!used.has(letter)) return letter;
  }
  return String.fromCharCode(65 + teams.length);
}
function addTeam() {
  if (teams.length < 6) { teams.push({ name: `Team ${nextTeamLetter()}` }); buildTeamsList(); }
}
function removeTeamAt(i) {
  if (teams.length <= 2) return;
  teams.splice(i, 1);
  buildTeamsList();
}
buildTeamsList();

// ═══ GAME STATE (multi-team, multi-round) ═══
let penaltyOn = document.getElementById('penaltyToggle').checked;
document.getElementById('penaltyToggle').addEventListener('change', e => { penaltyOn = e.target.checked; });

let gameTimeLeft = 60;
let gameTimerInterval = null;
let isPaused = false;

let scores = [];            // one running total per team
let currentTeamIdx = 0;
let currentRound = 1;
let wordPool = [];           // { word, cat, hint? }, shuffled
let usedWords = new Set();   // words already seen this game
let turnWords = [];          // words shown during the turn in progress: { word, cat, result }
let currentWordObj = null;

function shuffleArray(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
}

function buildWordPool() {
  wordPool = [];
  selectedTopics.forEach(catId => {
    const cat = CATEGORIES.find(c => c.id === catId);
    (WORDS[catId] || []).forEach(w => wordPool.push({ ...w, cat: cat ? cat.label : '' }));
  });
  shuffleArray(wordPool);
}

function getNextWord() {
  const available = wordPool.filter(w => !usedWords.has(w.word));
  if (available.length === 0) {
    // everyone's been through the pool at least once — reset, but keep
    // this turn's own words out of rotation so we don't repeat instantly
    usedWords = new Set(turnWords.map(w => w.word));
    const fresh = wordPool.filter(w => !usedWords.has(w.word));
    return fresh[0] || wordPool[0];
  }
  return available[0];
}

// called from the Teams screen's Play button
function startGame() {
  scores = teams.map(() => 0);
  currentTeamIdx = 0;
  currentRound = 1;
  usedWords = new Set();
  buildWordPool();
  goToTurnScreen();
}

function goToTurnScreen() {
  const team = teams[currentTeamIdx];
  document.getElementById('turnRoundLabel').textContent = `Round ${currentRound} of ${roundsVal}`;
  document.getElementById('turnTeamName').textContent = team.name;
  const catNames = selectedTopics.map(id => CATEGORIES.find(c => c.id === id)?.label).filter(Boolean).join(', ');
  document.getElementById('turnCatList').textContent = catNames;
  showScreen('screenTurn');
}

function beginTurn() {
  turnWords = [];
  gameTimeLeft = timerVal;
  const team = teams[currentTeamIdx];
  document.getElementById('gameRoundLabel').textContent = `Round ${currentRound} · ${team.name}`;
  document.getElementById('gameTeamName').textContent = team.name;
  loadNextWord();
  setupTimerBorder();
  updateTimerUI();
  if (gameTimerInterval) clearInterval(gameTimerInterval);
  gameTimerInterval = setInterval(() => {
    if (isPaused) return;
    gameTimeLeft--;
    updateTimerUI();
    if (gameTimeLeft <= 0) {
      clearInterval(gameTimerInterval);
      setTimeout(goToResults, 500);
    }
  }, 1000);
}

function loadNextWord() {
  if (wordPool.length === 0) {
    document.getElementById('wordCat').textContent = '';
    document.getElementById('wordMain').textContent = 'No words in this category yet';
    currentWordObj = null;
    return;
  }
  currentWordObj = getNextWord();
  usedWords.add(currentWordObj.word);
  document.getElementById('wordCat').textContent = currentWordObj.cat;
  document.getElementById('wordMain').textContent = currentWordObj.word;
}

// measures the actual rendered card and draws two matching rounded-rect
// outlines on top of it: a static "track" and a colored "fill" whose
// dash-offset we animate — same trick as a circular countdown ring,
// just traced clockwise around the card's rounded corners instead
function setupTimerBorder() {
  const card = document.getElementById('wordCard');
  const svg = document.getElementById('timerBorderSvg');
  const track = document.getElementById('timerBorderTrack');
  const fill = document.getElementById('timerBorderFill');
  const w = card.clientWidth, h = card.clientHeight;
  if (!w || !h) return;
  const sw = 3, r = 17;
  svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  [track, fill].forEach(rect => {
    rect.setAttribute('x', sw / 2);
    rect.setAttribute('y', sw / 2);
    rect.setAttribute('width', w - sw);
    rect.setAttribute('height', h - sw);
    rect.setAttribute('rx', r);
    rect.setAttribute('ry', r);
  });
  fill.dataset.length = fill.getTotalLength();
}
window.addEventListener('resize', () => {
  if (document.getElementById('screenGame').classList.contains('active')) {
    setupTimerBorder();
    updateTimerUI();
  }
});

function updateTimerUI() {
  const pct = Math.max(0, gameTimeLeft / timerVal);
  const fill = document.getElementById('timerBorderFill');
  const L = parseFloat(fill.dataset.length) || 0;
  fill.style.strokeDasharray = L;
  fill.style.strokeDashoffset = L * (1 - pct);
}

function pressBtn(id) {
  const btn = document.getElementById(id);
  btn.classList.add('press');
  setTimeout(() => btn.classList.remove('press'), 150);
}

function handleGot() {
  if (!currentWordObj) return;
  playCoinSound();
  pressBtn('btnGot');
  turnWords.push({ word: currentWordObj.word, cat: currentWordObj.cat, result: 'correct' });
  loadNextWord();
}

function handleSkip() {
  if (!currentWordObj) return;
  pressBtn('btnSkip');
  if (penaltyOn) {
    playHitSound();
  } else {
    playNeutralTick();
  }
  turnWords.push({ word: currentWordObj.word, cat: currentWordObj.cat, result: 'skip' });
  loadNextWord();
}

// ═══ RESULTS SCREEN (per turn) ═══
function goToResults() {
  const team = teams[currentTeamIdx];
  document.getElementById('resultsRoundLabel').textContent = `Round ${currentRound} · Results`;
  document.getElementById('resultsTeamName').textContent = team.name;

  let delta = 0;
  turnWords.forEach(w => {
    if (w.result === 'correct') delta += 1;
    if (w.result === 'skip' && penaltyOn) delta -= 1;
  });
  scores[currentTeamIdx] = (scores[currentTeamIdx] || 0) + delta;

  renderRoundSummary();
  renderResultsList();

  const isLast = (currentRound === roundsVal && currentTeamIdx === teams.length - 1);
  document.getElementById('resultsNextBtn').textContent = isLast ? 'See Final Scores' : 'Next Team';

  showScreen('screenResults');
}

function renderRoundSummary() {
  const correct = turnWords.filter(w => w.result === 'correct').length;
  const skipped = turnWords.filter(w => w.result === 'skip').length;
  const penalty = penaltyOn ? skipped : 0;
  const roundScore = correct - penalty;
  const el = document.getElementById('roundScoreSummary');
  el.innerHTML = `
    <div class="team-count-row" style="flex-wrap:wrap;gap:10px">
      <div style="display:flex;gap:18px;flex-wrap:wrap">
        <div><div class="mode-label">Correct</div><div style="font-family:'DM Serif Display',serif;font-size:26px;color:#4ade80">${correct}</div></div>
        <div><div class="mode-label">Skipped</div><div style="font-family:'DM Serif Display',serif;font-size:26px;color:#f87171">${skipped}</div></div>
        ${penaltyOn ? `<div><div class="mode-label">Penalty</div><div style="font-family:'DM Serif Display',serif;font-size:26px;color:#ff6b35">−${penalty}</div></div>` : ''}
      </div>
      <div>
        <div class="mode-label">Round score</div>
        <div style="font-family:'DM Serif Display',serif;font-size:32px">${roundScore > 0 ? '+' : ''}${roundScore}</div>
      </div>
    </div>`;
}

function renderResultsList() {
  const list = document.getElementById('resultsList');
  list.innerHTML = '';
  turnWords.forEach((w, i) => {
    const item = document.createElement('div');
    item.className = `result-item ${w.result}`;
    let badge = w.result === 'correct'
      ? `<span class="badge badge-correct">✓ correct</span>`
      : `<span class="badge badge-skip">✕ skip</span>${penaltyOn ? ' <span class="penalty-tag">−1</span>' : ''}`;
    item.innerHTML = `
      <div>
        <div class="result-word">${w.word}</div>
        <div class="result-word-cat">${w.cat}</div>
      </div>
      <div style="display:flex;align-items:center;gap:6px">${badge}</div>`;
    item.onclick = () => toggleResult(i);
    list.appendChild(item);
  });
}

function toggleResult(idx) {
  const w = turnWords[idx];
  if (w.result === 'correct') {
    scores[currentTeamIdx] -= 1;
    if (penaltyOn) scores[currentTeamIdx] -= 1;
    w.result = 'skip';
  } else {
    if (penaltyOn) scores[currentTeamIdx] += 1;
    scores[currentTeamIdx] += 1;
    w.result = 'correct';
  }
  renderRoundSummary();
  renderResultsList();
}

function handleResultsNext(btn) {
  ensureAudio();
  playConfirmBlip();
  btn.classList.remove('press'); void btn.offsetWidth; btn.classList.add('press');
  setTimeout(() => btn.classList.remove('press'), 150);
  setTimeout(nextTurn, 560);
}

function nextTurn() {
  const isLast = (currentRound === roundsVal && currentTeamIdx === teams.length - 1);
  if (isLast) { showEndScreen(); return; }
  currentTeamIdx++;
  if (currentTeamIdx >= teams.length) { currentTeamIdx = 0; currentRound++; }
  goToTurnScreen();
}

const SFX_VICTORY_SRC = 'data:audio/mpeg;base64,';
const SFX_SKIP_PENALTY_SRC = 'data:audio/mpeg;base64,';
function playAudioClip(src, volume) {
  if (!soundOn) return;
  try {
    const a = new Audio(src);
    a.volume = volume != null ? volume : 0.6;
    a.play().catch(() => {});
  } catch (e) {}
}

// pleasant "got it" chime — two gentle sine/triangle notes rising
// a major third, no harsh edges, but clearly audible
function playCoinSound() {
  if (!soundOn) return;
  ensureAudio();
  tone(784,  0,    0.10, 'sine', 0.20);
  tone(988,  0.07, 0.22, 'triangle', 0.19);
}

// "skip with penalty" cue — real retro "took damage" sound effect
function playHitSound() {
  playAudioClip(SFX_SKIP_PENALTY_SRC, 0.7);
}

// "skip, no penalty" cue — two flat, equal-pitch triangle taps (no
// melodic rise or fall), so it reads as neutral rather than good or bad,
// while staying loud and distinct from the Next/Play confirm blip
function playNeutralTick() {
  if (!soundOn) return;
  ensureAudio();
  tone(392, 0,    0.08, 'triangle', 0.24);
  tone(392, 0.10, 0.10, 'triangle', 0.22);
}

// ═══ PAUSE MENU — theme + sound now live here instead of the onboarding
// corner toggle, plus a Quit that needs a second tap to confirm ═══
function openPause() {
  isPaused = true;
  resetQuitArm();
  document.getElementById('pauseOverlay').classList.add('show');
}
function closePause() {
  isPaused = false;
  resetQuitArm();
  document.getElementById('pauseOverlay').classList.remove('show');
}

let quitArmed = false;
let quitArmTimeout = null;
function resetQuitArm() {
  quitArmed = false;
  if (quitArmTimeout) clearTimeout(quitArmTimeout);
  const btn = document.getElementById('quitBtn');
  if (btn) btn.textContent = 'Quit';
}
function handleQuit() {
  const btn = document.getElementById('quitBtn');
  if (!quitArmed) {
    quitArmed = true;
    btn.textContent = 'Tap again to quit';
    quitArmTimeout = setTimeout(() => { quitArmed = false; btn.textContent = 'Quit'; }, 2500);
    return;
  }
  clearTimeout(quitArmTimeout);
  quitArmed = false;
  btn.textContent = 'Quit';
  if (gameTimerInterval) clearInterval(gameTimerInterval);
  isPaused = false;
  document.getElementById('pauseOverlay').classList.remove('show');
  showScreen('screenMenu');
}

// ═══ END SCREEN — trophy artwork, supplied as a finished pixel-art PNG
// by the user. The rays/sparkles in that source image are NOT reused —
// these are freshly built as SVG (gold sunburst lines that slowly
// rotate + scattered sparkle squares that twinkle on their own beat),
// so they can be animated independently behind the static trophy image.
const TROPHY_IMG_SRC = 'data:image/png;base64,';
function setupTrophyArt() {
  const img = document.getElementById('trophyImg');
  if (img.dataset.built) return;
  img.src = TROPHY_IMG_SRC;
  img.dataset.built = '1';
}

// confetti: fresh burst of colored pieces (one per level color, cycling),
// falling at random speed/drift from above the screen
function buildConfetti() {
  const layer = document.getElementById('confettiLayer');
  layer.innerHTML = '';
  const PIECE_COUNT = 34;
  for (let i = 0; i < PIECE_COUNT; i++) {
    const piece = document.createElement('div');
    piece.className = 'confetti-piece';
    const color = LEVEL_COLORS[i % LEVEL_COLORS.length];
    const size = 6 + Math.random() * 6;
    const left = Math.random() * 100;
    const duration = (6 + Math.random() * 5).toFixed(2);
    const delay = (Math.random() * 4).toFixed(2);
    const drift = Math.round((Math.random() - 0.5) * 220);
    const spin = Math.round(360 + Math.random() * 540);
    piece.style.left = left + 'vw';
    piece.style.width = size + 'px';
    piece.style.height = (size * 0.4) + 'px';
    piece.style.background = color;
    piece.style.setProperty('--drift', drift + 'px');
    piece.style.setProperty('--spin', spin + 'deg');
    piece.style.animationDuration = duration + 's';
    piece.style.animationDelay = delay + 's';
    layer.appendChild(piece);
  }
}

// victory fanfare: "ta-ta-ta-ta-DAM" — three short staccato notes,
// a rising note, then a held chord
// victory sound — real retro coin sound effect
function playVictoryFanfare() {
  playAudioClip(SFX_VICTORY_SRC, 0.75);
}

function showEndScreen() {
  setupTrophyArt();
  const ranked = teams
    .map((t, i) => ({ name: t.name, score: scores[i] || 0, color: LEVEL_COLORS[i % LEVEL_COLORS.length] }))
    .sort((a, b) => b.score - a.score);

  document.getElementById('endTeamName').textContent = ranked[0].name;
  const winnerScore = ranked[0].score;
  document.getElementById('endScore').textContent = winnerScore + (winnerScore === 1 ? ' point' : ' points');

  const fsEl = document.getElementById('finalScores');
  fsEl.innerHTML = '';
  ranked.forEach((t, i) => {
    const row = document.createElement('div');
    row.className = 'score-row' + (i === 0 ? ' winner' : '');
    row.innerHTML = `
      <div class="row" style="gap:10px;display:flex;align-items:center">
        <div class="team-dot" style="background:${t.color}"></div>
        <span>${t.name}</span>
        ${i === 0 ? '<span style="font-size:11px">🏆</span>' : ''}
      </div>
      <div class="score-val" style="color:${t.color}">${t.score}</div>`;
    fsEl.appendChild(row);
  });

  showScreen('screenEnd');
  buildConfetti();
  playVictoryFanfare();
}

function handlePlayAgain() {
  setTimeout(() => showScreen('screenMenu'), 300);
}
